-- ============================================================
-- CoachOS Kettlebell Specialist — WKSF Ranking Import (v2.4.354)
--
-- Bron: WKSF Ranking 10'-12' Men/Women, WKSF Ranking 30'-60'
-- Men/Women (wksf.site/rankings/, "Check All Ranks Available").
-- Getranscribeerd uit vier door de gebruiker aangeleverde screenshots,
-- teruggegeven en bevestigd door de gebruiker als importbron.
--
-- BLOCK A/B: elke rankingtabel bevat twee naast elkaar gelegen
-- kolomblokken (A: MSEC/MS/CMS/Rank1/2/3, B: CMS/Rank1/2/3). De
-- officiële betekenis (welk kettlebellgewicht bij welk blok hoort)
-- is NIET bevestigd — daarom bell_weight_kg = NULL op ALLE 720
-- rijen, ranking_block legt A/B vast als neutraal, herleidbaar feit.
--
-- TWEE BRONANOMALIEËN (bewust niet gecorrigeerd, exact zoals
-- getranscribeerd — 'onbekend is beter dan fout'):
-- 1. Biathlon 10' Men, gewichtscategorie 95: MSEC/MS (191/126)
--    identiek aan categorie 80 — mogelijk brontypefout, niet geverifieerd.
-- 2. Jerk 60' Women, middelste rij: categorielabel '95' i.p.v. het
--    verwachte 65 (tabel gebruikt verder alleen 58/65/over65) — niet
--    geverifieerd, letterlijk overgenomen.
-- Beide gemarkeerd met source_status = 'source_anomaly'.
-- ============================================================

-- ── Schema-uitbreiding ───────────────────────────────────────
alter table kettlebell_classifications add column if not exists ranking_block text check (ranking_block in ('A', 'B'));
alter table kettlebell_classifications add column if not exists source_status text not null default 'unresolved_block_weight' check (source_status in ('verified', 'unresolved_block_weight', 'source_anomaly'));

comment on column kettlebell_classifications.ranking_block is
  'A of B — de twee naast elkaar gelegen kolomblokken in de WKSF-rankingtabellen. Betekenis (kettlebellgewicht) nog niet officieel bevestigd.';
comment on column kettlebell_classifications.source_status is
  'unresolved_block_weight = data geverifieerd, bell_weight_kg nog onbekend. source_anomaly = brontekst zelf bevat een onopgeloste onduidelijkheid. verified = bell-weight-mapping bevestigd (nog niet in gebruik).';

-- ── WKSF-rulebook-referentie ─────────────────────────────────
-- Alle 720 rijen refereren naar hetzelfde actieve WKSF 2023-2027-rulebook.

insert into kettlebell_classifications
  (rulebook_id, discipline, sex, bodyweight_class, ranking_block, class_name, required_reps, required_duration_sec, source_reference, source_status)
select r.id, v.discipline, v.sex, v.bodyweight_class, v.ranking_block, v.class_name, v.required_reps, v.duration_sec, v.source_reference, v.source_status
from kettlebell_rulebooks r
cross join (values
  ('long_cycle_10', 600, 'male', '63', 'A', 'MSEC', 54, 'WKSF Ranking 10''-12'' Men (wksf.site/rankings/)', 'unresolved_block_weight'),
